import { FulfilmentService } from "../application/fulfilment-service";
import { createApp } from "./http-app";
import { InMemoryOrderRepository, InMemoryProductRepository } from "./in-memory-repositories";

const service = new FulfilmentService(new InMemoryProductRepository(), new InMemoryOrderRepository());
service.addProduct("widget", "Widget", 100);
service.addProduct("gadget", "Gadget", 50);

const port = Number(process.env.PORT ?? 3000);
createApp(service).listen(port, () => {
  console.log(`Order fulfilment API listening on port ${port}`);
});

